import{_ as i,a0 as l,w as o,s as d,ao as r,I as p,x as a,a1 as e,A as t}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const C=JSON.parse('{"title":"用 bash 倒计时日期 | LCTT x X-CMD","titleTemplate":false,"description":"用 bash 倒计时日期 | LCTT (201912) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"用 bash 倒计时日期 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"用 bash 倒计时日期 | LCTT (201912) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201912/20191209 Counting down the days using bash","title":"用 bash 倒计时日期","tag":"201912","desc":""},"relativePath":"201912/20191209 Counting down the days using bash.md","filePath":"[post].md"}'),h={name:"201912/20191209 Counting down the days using bash.md"};function u(c,s,g,b,k,m){const n=l("Link");return o(),d("div",null,[s[15]||(s[15]=r(`<h1 id="用-bash-倒计时日期" tabindex="-1">用 bash 倒计时日期 <a class="header-anchor" href="#用-bash-倒计时日期" aria-label="Permalink to “用 bash 倒计时日期”">​</a></h1><blockquote><p>需要知道重要事件发生前有多少天吗？让 Linux bash 和 date 命令可以帮助你！</p></blockquote><p><img src="https://img.linux.net.cn/data/attachment/album/201912/13/140725vdc3c7zj0o7ozc7j.jpg" alt=""></p><p>随着即将来临的重要假期，你可能需要提醒你还要准备多久。</p><p>幸运的是，你可以从 <code>date</code> 命令获得很多帮助。在本篇中，我们将研究 <code>date</code> 和 bash 脚本如何告诉你从今天到你预期的事件之间有多少天。</p><p>首先，在进行之前有几个提示。<code>date</code> 命令的 <code>%j</code> 选项将以 1 至 366 之间的数字显示当前日期。如你所想的一样，1 月 1 日将显示为 1，12 月 31 日将显示为 365 或 366，这取决于是否是闰年。继续尝试。你应该会看到以下内容：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ date +%j</span></span>
<span class="line"><span>339</span></span></code></pre></div><p>但是，你可以通过以下方式，在 <code>date</code> 命令中得到一年中<em>任何</em>一天的数字：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ date -d &quot;Mar 18&quot; +%j</span></span>
<span class="line"><span>077</span></span></code></pre></div><p>要记住的是，即使该日期是过去的日期，上面命令也会向你显示<em>当年</em>的日期。但是，你可以在命令中添加年来修复该问题：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ date -d &quot;Apr 29&quot; +%j</span></span>
<span class="line"><span>119</span></span>
<span class="line"><span>$ date -d &quot;Apr 29 2020&quot; +%j</span></span>
<span class="line"><span>120</span></span></code></pre></div><p>在闰年中，4 月 29 日将是一年的 120 天，而不是 119 天。</p><p>如果你想倒数圣诞节之前的日子并且不想在挂历上留下指纹，你可以使用以下脚本：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>#!/bin/sh</span></span>
<span class="line"><span></span></span>
<span class="line"><span>XMAS=\`date -d &quot;Dec 25&quot; +%j\`</span></span>
<span class="line"><span>TODAY=\`date +%j\`</span></span>
<span class="line"><span>DAYS=$(($XMAS - $TODAY))</span></span>
<span class="line"><span></span></span>
<span class="line"><span>case $DAYS in</span></span>
<span class="line"><span>  0) echo &quot;It&#39;s today! Merry Christmas!&quot;;;</span></span>
<span class="line"><span>  [0-9]*) echo &quot;$DAYS days remaining&quot;;;</span></span>
<span class="line"><span>  -[0-9]*) echo &quot;Oops, you missed it&quot;;;</span></span>
<span class="line"><span>esac</span></span></code></pre></div><p>在此脚本中，我们获取 12 月 25 日和今天的日期，然后相减。如果结果是正数，我们将显示剩余天数。如果为零，则发出 “Merry Christmas” 的消息，如果为负，那么仅告诉运行脚本的人他们错过了假期。也许他们沉迷在蛋酒中了。</p><p><code>case</code> 语句由用来打印信息的语句组成，当剩余时间等于 0，或任意数字或以 <code>-</code> 符号开头的数字（也就是过去）分别打印不同的信息。</p><p>对于人们想要关注的任何日期，都可以使用相同方法。实际上，我们可以要求运行脚本的人员提供日期，然后让他们知道从现在到那天还有多少天。这个脚本是这样的。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>#!/bin/sh</span></span>
<span class="line"><span></span></span>
<span class="line"><span>echo -n &quot;Enter event date (e.g., June 6): &quot;</span></span>
<span class="line"><span>read dt</span></span>
<span class="line"><span>EVENT=\`date -d &quot;$dt&quot; +%j\`</span></span>
<span class="line"><span>TODAY=\`date +%j\`</span></span>
<span class="line"><span>DAYS=\`expr $EVENT - $TODAY\`</span></span>
<span class="line"><span></span></span>
<span class="line"><span>case $DAYS in</span></span>
<span class="line"><span>  0) echo &quot;It&#39;s today!&quot;;;</span></span>
<span class="line"><span>  [0-9]*) echo &quot;$DAYS days remaining&quot;;;</span></span>
<span class="line"><span>  -[0-9]*) echo &quot;Oops, you missed it&quot;;;</span></span>
<span class="line"><span>esac</span></span></code></pre></div><p>使用此脚本会遇到的一个问题，如果运行该脚本的人希望知道到第二年这个特殊日子还有多少天，他们会感到失望。即使他们输入日期时提供了年，<code>date -d</code> 命令仍将仅提供今年中的天数，而不会提供从现在到那时的天数。</p><p>计算从今天到某年的日期之间的天数可能有些棘手。你需要包括所有中间年份，并注意那些闰年。</p><h3 id="使用-unix-纪元时间" tabindex="-1">使用 Unix 纪元时间 <a class="header-anchor" href="#使用-unix-纪元时间" aria-label="Permalink to “使用 Unix 纪元时间”">​</a></h3><p>计算从现在到某个特殊日期之间的天数的另一种方法是利用 Unix 系统存储日期的方法。如果将自 1970 年 1 月 1 日开始的秒数转换为天数，那么就可以很容易地执行此操作，如下脚本所示：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>#!/bin/bash</span></span>
<span class="line"><span></span></span>
<span class="line"><span>echo -n &quot;Enter target date (e.g., Mar 18 2021)&gt; &quot;</span></span>
<span class="line"><span>read target_date</span></span>
<span class="line"><span>today=\`echo $(($(date --utc --date &quot;$1&quot; +%s)/86400))\`</span></span>
<span class="line"><span>target=\`echo $(($(date --utc --date &quot;$target_date&quot; +%s)/86400))\`</span></span>
<span class="line"><span>days=\`expr $target - $today\`</span></span>
<span class="line"><span>echo &quot;$days days until $target_date&quot;</span></span></code></pre></div><p>解释一下，86400 是一天中的秒数。将自 Unix 纪元开始以来的秒数除该数即为天数。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ ./countdown</span></span>
<span class="line"><span>Enter target date (e.g., Mar 18 2021)&gt; Mar 18 2020</span></span>
<span class="line"><span>104 days until Mar 18 2020</span></span></code></pre></div><hr>`,26)),p("p",null,[s[1]||(s[1]=a("via: ",-1)),e(n,{href:"https://www.networkworld.com/article/3487712/counting-down-the-days-using-bash.html"},{default:t(()=>[...s[0]||(s[0]=[a("https://www.networkworld.com/article/3487712/counting-down-the-days-using-bash.html",-1)])]),_:1})]),p("p",null,[s[6]||(s[6]=a("作者：",-1)),e(n,{href:"https://www.networkworld.com/author/Sandra-Henry_Stocker/"},{default:t(()=>[...s[2]||(s[2]=[a("Sandra Henry-Stocker",-1)])]),_:1}),s[7]||(s[7]=a(" 选题：",-1)),e(n,{href:"https://github.com/lujun9972"},{default:t(()=>[...s[3]||(s[3]=[a("lujun9972",-1)])]),_:1}),s[8]||(s[8]=a(" 译者：",-1)),e(n,{href:"https://github.com/geekpi"},{default:t(()=>[...s[4]||(s[4]=[a("geekpi",-1)])]),_:1}),s[9]||(s[9]=a(" 校对：",-1)),e(n,{href:"https://github.com/wxy"},{default:t(()=>[...s[5]||(s[5]=[a("wxy",-1)])]),_:1})]),p("p",null,[s[12]||(s[12]=a("本文由 ",-1)),e(n,{href:"https://github.com/LCTT/TranslateProject"},{default:t(()=>[...s[10]||(s[10]=[a("LCTT",-1)])]),_:1}),s[13]||(s[13]=a(" 原创编译，",-1)),e(n,{href:"https://linux.cn/"},{default:t(()=>[...s[11]||(s[11]=[a("Linux中国",-1)])]),_:1}),s[14]||(s[14]=a(" 荣誉推出",-1))])])}const q=i(h,[["render",u]]);export{C as __pageData,q as default};
